package quebec.culture.donnees;
import android.app.*;import android.os.*;import android.webkit.*;import android.widget.*;import java.net.*;
public class SearchActivity extends Activity{private EditText q;private Spinner scope;private WebView web;@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Recherche culturelle du Québec",28,true));r.addView(Ui.text(this,"Recherche dans les données ouvertes et sur le Web québécois : artistes, musées, festivals, films, livres, organismes, programmes et patrimoine.",14,false));q=new EditText(this);q.setHint("Ex. festival jazz Montréal, musée, auteur…");String pre=getIntent().getStringExtra("prefill");if(pre!=null)q.setText(pre);r.addView(q);scope=new Spinner(this);scope.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Tout — culture Québec","Données Québec","Ministère de la Culture et des Communications","Web québécois"}));r.addView(scope);Button search=Ui.primary(this,"Rechercher");search.setOnClickListener(v->go());r.addView(search);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.setWebViewClient(new WebViewClient());r.addView(web,new LinearLayout.LayoutParams(-1,Ui.dp(this,700)));setContentView(Ui.wrap(this,r));if(getIntent().getBooleanExtra("auto_search",false)&&pre!=null)go();}private void go(){String s=q.getText().toString().trim();if(s.isEmpty())return;try{String enc=URLEncoder.encode(s,"UTF-8"),u;switch(scope.getSelectedItemPosition()){case 1:u="https://www.donneesquebec.ca/recherche/dataset/?q="+enc;break;case 2:u="https://www.google.com/search?q="+URLEncoder.encode("site:quebec.ca culture communication "+s,"UTF-8");break;case 3:u="https://www.google.com/search?q="+URLEncoder.encode(s+" Québec culture","UTF-8");break;default:u="https://www.bing.com/search?q="+URLEncoder.encode(s+" culture Québec","UTF-8");}web.loadUrl(u);}catch(Exception ignored){}}}
